{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Diflunisal, a carboxylic acid-containing salicylate, had absolute oral bioavailability of 89.5% in a volunteer, showing that acidic polar drugs of this class can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Telmisartan, a carboxylic acid-containing drug, had absolute bioavailability of 42% at 40 mg in fasting volunteers, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Meclofenamate, a halogenated anthranilic acid NSAID, has human bioavailability above 85%, supporting high absorption for a close carboxylic acid analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Flufenamic acid, another anthranilic acid with a trifluoromethyl group, shows good oral bioavailability in humans, supporting high F for the query's carboxylic acid/furfurylamine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Celecoxib, a sulfonamide-containing drug, has oral bioavailability of 20-40%; although the lower end of the range, it still meets the F >= 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Pazopanib, a sulfonamide-containing drug, had absolute bioavailability of 21.4% in cancer patients, just above the threshold, supporting high.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Encorafenib, a sulfonamide-containing drug, has ~85% oral bioavailability in humans, supporting high for a sulfonamide-containing query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Query is furosemide. All transferable human bioavailability evidence from close structural analogues (carboxylic acid/sulfonamide drugs) is at or above 20%, with most values 40-90%; therefore F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct furosemide absolute bioavailability measurement in the supplied evidence set.",
    "No cystic fibrosis-specific bioavailability data; disease-related malabsorption could lower F but is unlikely to drop it below 20% given the high baseline."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

